    public static Obj assess(Obj payload,Value actionComponents){require(payload!=null,"combat-entry EU input must be an object");ObjectNode value=(ObjectNode)OpportunityJson.toNode(payload);ObjectNode base=base(value);if(actionComponents!=null&&actionComponents!=OpportunityJson.Nil.INSTANCE)return immutable(CombatEntryEuActions.assess(value,OpportunityJson.toNode(actionComponents),base));return immutable(base);}
    public static Obj assess(Obj payload){return assess(payload,null);}
    private static void unexpected(JsonNode value,JsonNode allowed,String prefix,List<String> errors){value.properties().forEach(e->{String path=prefix.isEmpty()?e.getKey():prefix+"."+e.getKey();JsonNode nested=allowed.get(e.getKey());if(nested==null)errors.add(path+"_unexpected");else if(nested.isObject()&&e.getValue().isObject())unexpected(e.getValue(),nested,path,errors);});}
