    private static boolean integerLikePython(JsonNode value){return integral(value)||value!=null&&value.isBoolean();}
    private static BigInteger pythonInteger(JsonNode value){return value.isBoolean()?(value.booleanValue()?BigInteger.ONE:BigInteger.ZERO):n(value);}
